-- Edition line-ups (linked to People by exact name when there is a match)
insert into edition_lineup (edition_id, person_id, name, role, sort_order)
select e.id, (select pe.id from people pe where pe.name = m.name limit 1), m.name, m.role, m.ord
from editions e join projects p on p.id = e.project_id
cross join (values ('Vesna Šouc', 'Guest conductor', 1), ('Ana Krstajic', 'Composer', 2), ('Tanyaradzwa Tawengwa', 'Composer', 3), ('Ghiya Rushidat', 'Composer', 4), ('Valerie Naranjo', 'Composer', 5), ('Morena Galán', 'Composer', 6), ('Ethel Smythe', 'Composer', 7), ('Aida Saco', 'Composer', 8), ('Niloufar Nourbakhsh', 'Composer', 9)) as m(name, role, ord)
where p.slug = 'global-women-in-music' and e.year = '2026'
  and not exists (select 1 from edition_lineup l where l.edition_id = e.id);

