-- Testimonials
insert into testimonials (slug, text, who, caption, photo, project_slug, published, home, sort_order) values ('gwim-1', 'This program is doing meaningful work for women and music. It was really empowering and inspiring to be part of this year’s event!', 'Female composer, Global Women in Music 2025', '', '{"src":"05-cita-compositora_IMG_5409.jpg","alt":"Composer smiling on stage with the orchestra behind her","pos":"50% 35%"}'::jsonb, 'global-women-in-music', true, true, 1) on conflict (slug) do nothing;
insert into testimonials (slug, text, who, caption, photo, project_slug, published, home, sort_order) values ('gwim-2', 'The invitation generated more than just an opportunity. It generated visibility, recognition, unity and for us, an unforgettable feeling of personal confidence that we will never forget. Music unites us all in a universal language and allows women to have that place of self worth.', 'Female conductors, Global Women in Music 2025', 'Twin sister conductors Josefa and Esperanza Velasco, GWIM 2025', '{"src":"gwim-2025-hermanas-velasco.jpg","alt":"Twin sister conductors Josefa and Esperanza Velasco","pos":"50% 50%"}'::jsonb, 'global-women-in-music', true, true, 2) on conflict (slug) do nothing;

